css:
.wrap {
  position: relative;
  display: inline-block;
  margin: 64px 16px 16px;
}

.trigger {
  padding: 8px 14px;
  border: 0;
  border-radius: 6px;
  background: #3f3f46;
  color: #fafafa;
}

.tip {
  position: absolute;
  top: -40px;
  left: 0;
  z-index: 1;
  padding: 6px 10px;
  border-radius: 4px;
  background: #18181b;
  color: #fafafa;
  font-size: 13px;
  white-space: nowrap;
}
